// syncEntry — glob paths (real temp filesystem)
// ---------------------------------------------------------------------------
describe('syncEntry (glob patterns)', () => {
  const tmpDirs: string[] = [];

  function makeTempDir(): string {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'dfiles-sync-test-'));
    tmpDirs.push(dir);
    return dir;
