    fs.rmSync(cacheDir, { recursive: true, force: true });
    mockGit.clone.mockRejectedValue(new Error('authentication required'));

    // Act / Assert
    await expect(ensureCached(TEST_URL, BRANCH)).rejects.toThrow('Failed to clone repository');
